"""
app.py — Flask glue between the browser UI and the ClaudeSession bridge.

Transport: Server-Sent Events for claude -> UI (one-way streaming, dead simple,
robust on the Flask dev server), plain POST for UI -> claude. Single local user,
so one global session.
"""
import json

from flask import Flask, Response, jsonify, request, send_from_directory

from bridge import ClaudeSession

app = Flask(__name__, static_folder="static", static_url_path="")

_session = None


def get_session():
    global _session
    if _session is None or not _session.alive:
        _session = ClaudeSession()
    return _session


@app.route("/")
def index():
    return send_from_directory("static", "index.html")


@app.route("/send", methods=["POST"])
def send():
    text = (request.get_json(silent=True) or {}).get("text", "").strip()
    if not text:
        return jsonify({"ok": False, "error": "empty"}), 400
    ok = get_session().send(text)
    return jsonify({"ok": ok})


@app.route("/new", methods=["POST"])
def new():
    global _session
    if _session:
        _session.stop()
    _session = ClaudeSession()
    return jsonify({"ok": True})


@app.route("/stream")
def stream():
    s = get_session()
    q = s.subscribe()

    def gen():
        # Replay capabilities to a late-joining / reconnecting UI.
        if s.last_init:
            yield _sse(s.last_init)
        try:
            while True:
                yield _sse(q.get())
        except GeneratorExit:
            s.unsubscribe(q)

    return Response(
        gen(),
        mimetype="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no",
                 "Connection": "keep-alive"},
    )


def _sse(obj):
    return "data: " + json.dumps(obj) + "\n\n"


if __name__ == "__main__":
    # Browser dev mode: open http://127.0.0.1:5014
    app.run(host="127.0.0.1", port=5014, threaded=True, use_reloader=False)

/* MIST Console — flat/sharp Cloud palette. Square corners, hairlines, no shadows. */
:root {
  --bg:        #0E1C2B;   /* deep Cloud night */
  --bg-2:      #11233440; /* translucent panel */
  --line:      #1f3b53;   /* hairline */
  --line-soft: #173044;
  --text:      #d7e6ef;
  --dim:       #6f8ba0;
  --teal:      #2bd4d4;   /* MIST accent (statusline 256-44) */
  --violet:    #9b8cff;
  --user:      #cfe8ff;
  --warn:      #ffb454;
  --err:       #ff6b6b;
  --mono: "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
}
* { box-sizing: border-box; }
html, body {
  margin: 0; height: 100%;
  background: var(--bg); color: var(--text);
  font-family: var(--mono); font-size: 13px; line-height: 1.55;
}
body { display: grid; grid-template-rows: auto 1fr auto; height: 100vh; }

/* ---- top bar ---- */
#topbar {
  display: flex; align-items: center; gap: 14px;
  padding: 8px 14px; border-bottom: 1px solid var(--line);
  background: #0c1825;
}
.brand { display: flex; align-items: baseline; gap: 8px; }
.logo { color: var(--teal); font-weight: 700; letter-spacing: 2px; }
.sub { color: var(--dim); font-size: 11px; text-transform: uppercase; letter-spacing: 1px; }
.meta { display: flex; gap: 6px; flex: 1; flex-wrap: wrap; }
.badge {
  border: 1px solid var(--line); color: var(--dim);
  padding: 2px 7px; font-size: 11px; white-space: nowrap;
}
#status[data-state="idle"]     { color: var(--dim); }
#status[data-state="thinking"] { color: var(--violet); border-color: var(--violet); }
#status[data-state="working"]  { color: var(--teal);   border-color: var(--teal); }
#status[data-state="error"]    { color: var(--err);    border-color: var(--err); }
.actions { display: flex; gap: 6px; }
button {
  font-family: var(--mono); font-size: 12px;
  background: transparent; color: var(--text);
  border: 1px solid var(--line); padding: 4px 10px; cursor: pointer;
}
button:hover { border-color: var(--teal); color: var(--teal); }

/* ---- log ---- */
#log { overflow-y: auto; padding: 16px 18px 40px; }
.msg { margin: 0 0 18px; max-width: 900px; }
.msg .who { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 4px; }
.msg.user .who   { color: var(--user); }
.msg.mist .who   { color: var(--teal); }
.msg.user .body  { color: var(--user); border-left: 2px solid #2a4866; padding-left: 10px; white-space: pre-wrap; }
.msg.mist .body  { color: var(--text); }

/* thinking */
.think {
  border: 1px solid var(--line-soft); border-left: 2px solid var(--violet);
  margin: 6px 0 10px; padding: 0;
}
.think > summary {
  cursor: pointer; color: var(--violet); font-size: 11px;
  padding: 4px 8px; list-style: none; text-transform: uppercase; letter-spacing: 1px;
}
.think > summary::-webkit-details-marker { display: none; }
.think .think-body { padding: 6px 10px; color: #9db3c6; white-space: pre-wrap; font-size: 12px; }

/* tool cards */
.tool {
  border: 1px solid var(--line); margin: 8px 0;
}
.tool .tool-head {
  display: flex; align-items: center; gap: 8px;
  background: #0f2030; padding: 5px 9px; color: var(--teal); font-size: 12px;
}
.tool .tool-head .tname { font-weight: 700; }
.tool .tool-head .tstate { margin-left: auto; color: var(--dim); font-size: 11px; }
.tool pre { margin: 0; padding: 8px 10px; overflow-x: auto; font-size: 12px; color: #b9ccdb; }
.tool .tool-result { border-top: 1px dashed var(--line); color: #9db3c6; max-height: 280px; overflow: auto; }

/* markdown body */
.body p { margin: 0 0 9px; }
.body pre {
  background: #0b1722; border: 1px solid var(--line);
  padding: 9px 11px; overflow-x: auto; margin: 8px 0;
}
.body code { background: #0b1722; border: 1px solid var(--line-soft); padding: 0 4px; }
.body pre code { border: 0; padding: 0; background: none; }
.body h1,.body h2,.body h3 { color: var(--teal); margin: 12px 0 6px; font-size: 14px; }
.body ul,.body ol { margin: 4px 0 9px; padding-left: 22px; }
.body a { color: var(--teal); }
.body blockquote { border-left: 2px solid var(--line); margin: 6px 0; padding-left: 10px; color: var(--dim); }
.cursor { display: inline-block; width: 7px; background: var(--teal); animation: blink 1s steps(1) infinite; }
@keyframes blink { 50% { opacity: 0; } }

.notice { color: var(--warn); border: 1px solid var(--warn); padding: 6px 10px; margin: 10px 0; font-size: 12px; }
.notice.err { color: var(--err); border-color: var(--err); }

/* ---- capabilities panel ---- */
#capPanel {
  position: fixed; top: 0; right: 0; width: 340px; height: 100%;
  background: #0c1825; border-left: 1px solid var(--line);
  display: flex; flex-direction: column; z-index: 20;
}
.capHead { display: flex; padding: 10px 12px; border-bottom: 1px solid var(--line); color: var(--teal); }
.capHead button { margin-left: auto; border: 0; font-size: 16px; }
.capBody { overflow-y: auto; padding: 10px 12px; }
.capBody h4 { color: var(--dim); font-size: 11px; text-transform: uppercase; margin: 12px 0 6px; }
.chips { display: flex; flex-wrap: wrap; gap: 4px; }
.chips span { border: 1px solid var(--line); padding: 1px 6px; font-size: 11px; color: #9db3c6; }
.chips span.pending { color: var(--warn); border-color: var(--warn); }

/* ---- composer ---- */
#composer {
  display: flex; gap: 8px; padding: 10px 14px;
  border-top: 1px solid var(--line); background: #0c1825;
}
#input {
  flex: 1; resize: none; max-height: 200px;
  background: #0b1722; color: var(--text); border: 1px solid var(--line);
  font-family: var(--mono); font-size: 13px; padding: 9px 11px; outline: none;
}
#input:focus { border-color: var(--teal); }
#sendBtn { padding: 0 18px; }
#sendBtn:disabled { opacity: .4; cursor: default; border-color: var(--line); color: var(--dim); }

#usage {
  position: fixed; bottom: 58px; right: 14px;
  font-size: 11px; color: var(--dim); pointer-events: none;
}

/* scrollbars */
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: #1d3span; background: #1d3a52; }
::-webkit-scrollbar-track { background: transparent; }

/* MIST Console front-end. Consumes the claude stream-json protocol over SSE
   and renders the entire UI ourselves. */
"use strict";

const $ = (s) => document.querySelector(s);
const log = $("#log");
const input = $("#input");
const sendBtn = $("#sendBtn");
const statusEl = $("#status");

let current = null;     // current assistant message render state
let blocks = {};        // index -> {type, el, toolName}
let toolInputs = {};    // index -> accumulated partial json string

/* ---------- tiny safe markdown ---------- */
function esc(s) {
  return s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
}
function md(src) {
  // fenced code first, protect with placeholders
  const fences = [];
  src = src.replace(/```(\w*)\n([\s\S]*?)```/g, (_, lang, code) => {
    fences.push(`<pre><code>${esc(code)}</code></pre>`);
    return `�${fences.length - 1}�`;
  });
  src = esc(src);
  src = src
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>")
    .replace(/^### (.*)$/gm, "<h3>$1</h3>")
    .replace(/^## (.*)$/gm, "<h2>$1</h2>")
    .replace(/^# (.*)$/gm, "<h1>$1</h1>")
    .replace(/^\s*[-*] (.*)$/gm, "<li>$1</li>")
    .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<a href="$2">$1</a>');
  src = src.replace(/(<li>[\s\S]*?<\/li>)/g, "<ul>$1</ul>").replace(/<\/ul>\s*<ul>/g, "");
  src = src
    .split(/\n{2,}/)
    .map((p) => (/^\s*<(h\d|ul|pre|blockquote)/.test(p) ? p : `<p>${p.replace(/\n/g, "<br>")}</p>`))
    .join("");
  src = src.replace(/�(\d+)�/g, (_, i) => fences[+i]);
  return src;
}

/* ---------- dom helpers ---------- */
function atBottom() { return log.scrollHeight - log.scrollTop - log.clientHeight < 60; }
function scroll() { log.scrollTop = log.scrollHeight; }
function el(tag, cls, html) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
}
function addMsg(role, who) {
  const wrap = el("div", "msg " + role);
  wrap.appendChild(el("div", "who", who));
  const body = el("div", "body");
  wrap.appendChild(body);
  log.appendChild(wrap);
  scroll();
  return body;
}
function notice(text, isErr) {
  const n = el("div", "notice" + (isErr ? " err" : ""), esc(text));
  log.appendChild(n);
  scroll();
}
function setStatus(state, label) {
  statusEl.dataset.state = state;
  statusEl.textContent = label || state;
}

/* ---------- assistant turn rendering ---------- */
function beginAssistant() {
  current = { body: addMsg("mist", "MIST"), text: "", textEl: null };
  blocks = {};
  toolInputs = {};
}
function ensureTextEl() {
  if (!current.textEl) {
    current.textEl = el("div", "md");
    current.body.appendChild(current.textEl);
  }
  return current.textEl;
}

function handleStreamEvent(ev) {
  const e = ev.event;
  if (!e) return;
  const wasBottom = atBottom();

  if (e.type === "message_start") {
    if (!current) beginAssistant();
  } else if (e.type === "content_block_start") {
    const idx = e.index;
    const cb = e.content_block || {};
    if (cb.type === "thinking") {
      const d = el("details", "think");
      d.appendChild(el("summary", null, "thinking"));
      const tb = el("div", "think-body");
      d.appendChild(tb);
      current.body.appendChild(d);
      blocks[idx] = { type: "thinking", el: tb };
    } else if (cb.type === "text") {
      blocks[idx] = { type: "text", el: ensureTextEl() };
    } else if (cb.type === "tool_use") {
      blocks[idx] = { type: "tool", el: makeToolCard(cb.name), name: cb.name };
      toolInputs[idx] = "";
    }
  } else if (e.type === "content_block_delta") {
    const b = blocks[e.index];
    const d = e.delta || {};
    if (!b) return;
    if (d.type === "thinking_delta") {
      b.el.textContent += d.thinking || "";
    } else if (d.type === "text_delta") {
      current.text += d.text || "";
      current.textEl.innerHTML = md(current.text) + '<span class="cursor">&nbsp;</span>';
    } else if (d.type === "input_json_delta") {
      toolInputs[e.index] += d.partial_json || "";
      b.pre.textContent = toolInputs[e.index];
    }
  } else if (e.type === "content_block_stop") {
    const b = blocks[e.index];
    if (b && b.type === "text" && current.textEl) {
      current.textEl.innerHTML = md(current.text);
    }
  }
  if (wasBottom) scroll();
}

function makeToolCard(name) {
  const card = el("div", "tool");
  const head = el("div", "tool-head");
  head.appendChild(el("span", "tname", esc(name || "tool")));
  const st = el("span", "tstate", "running…");
  head.appendChild(st);
  card.appendChild(head);
  const pre = el("pre");
  card.appendChild(pre);
  current.body.appendChild(card);
  const ref = { type: "tool", el: card, pre, state: st, name };
  return ref;
}

/* tool_use full input arrives on the assistant snapshot; tool_result on a user msg */
function finalizeToolInputs(message) {
  (message.content || []).forEach((c) => {
    if (c.type !== "tool_use") return;
    for (const idx in blocks) {
      const b = blocks[idx];
      if (b.type === "tool" && b.name === c.name && b.pre && !b.done) {
        try { b.pre.textContent = JSON.stringify(c.input, null, 2); } catch (_) {}
        b.id = c.id;
      }
    }
  });
}
function applyToolResults(message) {
  (message.content || []).forEach((c) => {
    if (c.type !== "tool_result") return;
    for (const idx in blocks) {
      const b = blocks[idx];
      if (b.type === "tool" && b.id === c.tool_use_id && !b.done) {
        b.done = true;
        b.state.textContent = c.is_error ? "error" : "done";
        if (c.is_error) b.state.style.color = "var(--err)";
        let txt = c.content;
        if (Array.isArray(txt)) txt = txt.map((p) => (p.text || "")).join("");
        const res = el("pre", "tool-result", esc(String(txt || "").slice(0, 6000)));
        b.el.appendChild(res);
      }
    }
  });
}

/* ---------- top-level event dispatch ---------- */
function onEvent(o) {
  switch (o.type) {
    case "system":
      if (o.subtype === "init") fillCaps(o);
      else if (o.subtype === "status") {
        if (o.status === "requesting") setStatus("thinking", "thinking");
      }
      break;
    case "stream_event":
      if (o.event && o.event.type === "message_start") setStatus("working", "responding");
      handleStreamEvent(o);
      break;
    case "assistant":
      if (!current) beginAssistant();
      finalizeToolInputs(o.message || {});
      break;
    case "user":
      applyToolResults(o.message || {});
      break;
    case "result":
      current = null;
      setStatus("idle", "idle");
      showUsage(o);
      break;
    case "stderr":
      if (/error|fatal|exception/i.test(o.text)) notice("stderr: " + o.text, true);
      break;
    case "process_exit":
      setStatus("error", "exited");
      notice("Claude process exited (code " + o.code + "). Press “new” to restart.", true);
      break;
    case "raw":
      break;
  }
}

function showUsage(r) {
  const u = r.usage || {};
  const cost = r.total_cost_usd != null ? "$" + r.total_cost_usd.toFixed(4) : "";
  const tok = (u.output_tokens != null) ? u.output_tokens + " out" : "";
  const ms = r.duration_ms ? (r.duration_ms / 1000).toFixed(1) + "s" : "";
  $("#usage").textContent = [tok, ms, cost].filter(Boolean).join("  ·  ");
}

/* ---------- capabilities ---------- */
function chips(id, items, pendingKey) {
  const c = $(id);
  c.innerHTML = "";
  (items || []).forEach((it) => {
    const name = typeof it === "string" ? it : it.name;
    const span = el("span", null, esc(name));
    if (typeof it === "object" && it.status && it.status !== "connected") span.classList.add("pending");
    c.appendChild(span);
  });
}
function fillCaps(init) {
  $("#model").textContent = init.model || "model —";
  $("#perm").textContent = "perm: " + (init.permissionMode || "—");
  $("#sid").textContent = "session " + String(init.session_id || "").slice(0, 8);
  chips("#capTools", init.tools);
  chips("#capMcp", init.mcp_servers);
  chips("#capSlash", init.slash_commands);
  chips("#capSkills", init.skills);
}

/* ---------- send ---------- */
async function send() {
  const text = input.value.trim();
  if (!text) return;
  addMsg("user", "Alex").textContent = text;
  input.value = "";
  input.style.height = "auto";
  setStatus("thinking", "thinking");
  beginAssistant();
  try {
    const r = await fetch("/send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    const j = await r.json();
    if (!j.ok) notice("Could not deliver message to Claude.", true);
  } catch (err) {
    notice("Send failed: " + err, true);
  }
}

/* ---------- wiring ---------- */
input.addEventListener("input", () => {
  input.style.height = "auto";
  input.style.height = Math.min(input.scrollHeight, 200) + "px";
});
input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); }
});
