let es = null;
function connect() {
  if (es) es.close();
  es = new EventSource("/stream");
  es.onmessage = (m) => { try { onEvent(JSON.parse(m.data)); } catch (_) {} };
  es.onerror = () => setStatus("error", "disconnected");
}
