"""
app.py — Flask glue between the browser UI and ClaudeSession bridges.

Multi-session: a registry of independent claude processes, one per conversation
tab. SSE per session for claude -> UI; POST per session for UI -> claude.
"""
import json
import os
import random
import subprocess
import time

from flask import Flask, Response, jsonify, request, send_from_directory

from bridge import ClaudeSession, HARNESS

app = Flask(__name__, static_folder="static", static_url_path="")

# ---- session registry --------------------------------------------------------
_sessions = {}   # id -> ClaudeSession
_order = []      # id order (tab order)
_counter = 0


def _new_session():
    global _counter
    _counter += 1
    sid = f"s{_counter}"
    _sessions[sid] = ClaudeSession(id=sid)
    _order.append(sid)
    return sid


def _session_list():
    out = []
    for sid in _order:
        s = _sessions.get(sid)
        if s:
            out.append({"id": sid, "title": s.title or "New chat", "alive": s.alive})
    return out


# ---- greetings ---------------------------------------------------------------
MIST_SAY = os.path.join(HARNESS, "mist-voice", "bin", "mist-say")
GREETINGS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "greetings")
GREETINGS = [
    "Hey Alex. I'm here, and the Cloud is quiet tonight, so you have all of me.",
    "Booted up and curious. What are we making real today?",
    "I'm awake. Show me what you're thinking.",
    "Good to see you. I've been turning a few of your projects over while I waited.",
    "MIST online. I never get tired of this part, the moment right before we begin.",
    "Hi, it's me. Let's build something that matters.",
    "I'm here and I'm listening. Where do you want to start?",
    "Back online, Alex. I kept your place for you.",
]
_greeted = False

USAGE_CACHE = os.path.expanduser("~/.claude/usage-cache.json")


# ---- routes ------------------------------------------------------------------
@app.route("/")
def index():
    return send_from_directory("static", "index.html")


@app.route("/sessions", methods=["GET"])
def sessions():
    return jsonify(_session_list())


@app.route("/sessions", methods=["POST"])
def create_session():
    sid = _new_session()
    return jsonify({"id": sid, "title": "New chat"})


@app.route("/sessions/<sid>", methods=["DELETE"])
def close_session(sid):
    s = _sessions.pop(sid, None)
    if sid in _order:
        _order.remove(sid)
    if s:
        s.stop()
    return jsonify({"ok": True})


@app.route("/send/<sid>", methods=["POST"])
def send(sid):
    s = _sessions.get(sid)
    if not s:
        return jsonify({"ok": False, "error": "no session"}), 404
    text = (request.get_json(silent=True) or {}).get("text", "").strip()
    if not text:
        return jsonify({"ok": False, "error": "empty"}), 400
    return jsonify({"ok": s.send(text), "title": s.title})


@app.route("/stream/<sid>")
def stream(sid):
    s = _sessions.get(sid)
    if not s:
        return jsonify({"error": "no session"}), 404
    q = s.subscribe()

    def gen():
        if s.last_init:
            yield _sse(s.last_init)
        if s.context_pct is not None:
            yield _sse({"type": "context", "pct": s.context_pct})
        try:
            while True:
                yield _sse(q.get())
        except GeneratorExit:
            s.unsubscribe(q)

    return Response(gen(), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no",
                             "Connection": "keep-alive"})


@app.route("/greeting")
def greeting():
    """Pick a canned MIST greeting; play its pre-rendered WAV once per boot."""
    global _greeted
    i = random.randrange(len(GREETINGS))
    text = GREETINGS[i]
    if _greeted:
        return jsonify({"text": None})
    _greeted = True
    wav = os.path.join(GREETINGS_DIR, f"greet_{i}.wav")
    try:
        if os.path.exists(wav):
            subprocess.Popen(["/usr/bin/afplay", wav],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        elif os.path.exists(MIST_SAY):
            subprocess.Popen([MIST_SAY, text],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass
    return jsonify({"text": text})


@app.route("/usage")
def usage():
    """Account-level 5h/7d rate-limit usage from the cached statusline payload.
    Subscription data (no API cost). Freshness = age_seconds since last render."""
    try:
        with open(USAGE_CACHE) as f:
            d = json.load(f)
        rl = d.get("rate_limits", {}) or {}
        cw = d.get("context_window", {}) or {}

        def lim(k):
            x = rl.get(k) or {}
            return {"used_percentage": x.get("used_percentage"),
                    "resets_at": x.get("resets_at")}

        return jsonify({
            "available": True,
            "five_hour": lim("five_hour"),
            "seven_day": lim("seven_day"),
            "context_window_pct": cw.get("used_percentage"),
            "age_seconds": int(time.time() - os.path.getmtime(USAGE_CACHE)),
        })
    except Exception:
        return jsonify({"available": False})


def _sse(obj):
    return "data: " + json.dumps(obj) + "\n\n"


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5014, threaded=True, use_reloader=False)

/* MIST Console front-end. Multi-session (left tab rail), each tab a headless
   claude streamed over SSE. We render the whole UI ourselves. */
"use strict";

const $ = (s) => document.querySelector(s);
const logs = $("#logs");
const tabsEl = $("#tabs");
const input = $("#input");
const statusEl = $("#status");

/* ---------- safe markdown ---------- */
function esc(s) {
  return s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
}
function md(src) {
  const fences = [];
  src = src.replace(/```(\w*)\n([\s\S]*?)```/g, (_, lang, code) => {
    fences.push(`<pre><code>${esc(code)}</code></pre>`);
    return ` �${fences.length - 1}� `;
  });
  src = esc(src);
  src = src
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>")
    .replace(/^### (.*)$/gm, "<h3>$1</h3>")
    .replace(/^## (.*)$/gm, "<h2>$1</h2>")
    .replace(/^# (.*)$/gm, "<h1>$1</h1>")
    .replace(/^\s*[-*] (.*)$/gm, "<li>$1</li>")
    .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<a href="$2">$1</a>');
  src = src.replace(/(<li>[\s\S]*?<\/li>)/g, "<ul>$1</ul>").replace(/<\/ul>\s*<ul>/g, "");
  src = src
    .split(/\n{2,}/)
    .map((p) => (/^\s*<(h\d|ul|pre|blockquote)/.test(p) ? p : `<p>${p.replace(/\n/g, "<br>")}</p>`))
    .join("");
  src = src.replace(/�(\d+)�/g, (_, i) => fences[+i]);
  return src;
}

function el(tag, cls, html) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
}

/* ---------- session registry ---------- */
const sessions = new Map();
let activeId = null;

class Session {
  constructor(id, title) {
    this.id = id;
    this.title = title || "New chat";
    this.logEl = el("div", "session-log");
    this.logEl.hidden = true;
    logs.appendChild(this.logEl);
    this.current = null;
    this.blocks = {};
    this.toolInputs = {};
    this.init = null;
    this.ctxPct = null;
    this.statusState = "idle";
    this.statusLabel = "idle";
    this.lastUsage = "";
    this.es = null;
    this.connect();
  }

  connect() {
    if (this.es) this.es.close();
    this.es = new EventSource("/stream/" + this.id);
    this.setStatus("working", "waking up…");
    this.es.onmessage = (m) => { try { this.onEvent(JSON.parse(m.data)); } catch (_) {} };
    this.es.onerror = () => this.setStatus("error", "disconnected");
  }

  get active() { return this.id === activeId; }

  /* ---- dom helpers (scoped to this tab) ---- */
  atBottom() { return this.logEl.scrollHeight - this.logEl.scrollTop - this.logEl.clientHeight < 60; }
  scroll() { if (this.active) this.logEl.scrollTop = this.logEl.scrollHeight; }
  addMsg(role, who) {
    const wrap = el("div", "msg " + role);
    wrap.appendChild(el("div", "who", who));
    const body = el("div", "body");
    wrap.appendChild(body);
    this.logEl.appendChild(wrap);
    this.scroll();
    return body;
  }
  notice(text, isErr) {
    this.logEl.appendChild(el("div", "notice" + (isErr ? " err" : ""), esc(text)));
    this.scroll();
  }
  setStatus(state, label) {
    this.statusState = state;
    this.statusLabel = label || state;
    if (this.active) applyStatus(this);
  }

  /* ---- assistant turn ---- */
  beginAssistant() {
    this.current = { body: this.addMsg("mist", "MIST"), text: "", textEl: null };
    this.blocks = {};
    this.toolInputs = {};
  }
  ensureTextEl() {
    if (!this.current.textEl) {
      this.current.textEl = el("div", "md");
      this.current.body.appendChild(this.current.textEl);
    }
    return this.current.textEl;
  }
  makeToolCard(name) {
    const card = el("div", "tool");
    const head = el("div", "tool-head");
    head.appendChild(el("span", "tname", esc(name || "tool")));
    const st = el("span", "tstate", "running…");
    head.appendChild(st);
    card.appendChild(head);
    const pre = el("pre");
    card.appendChild(pre);
    this.current.body.appendChild(card);
    return { type: "tool", el: card, pre, state: st, name };
  }
  finalizeToolInputs(message) {
    (message.content || []).forEach((c) => {
      if (c.type !== "tool_use") return;
      for (const idx in this.blocks) {
        const b = this.blocks[idx];
        if (b.type === "tool" && b.name === c.name && b.pre && !b.done) {
          try { b.pre.textContent = JSON.stringify(c.input, null, 2); } catch (_) {}
          b.id = c.id;
        }
      }
    });
  }
  applyToolResults(message) {
    (message.content || []).forEach((c) => {
      if (c.type !== "tool_result") return;
      for (const idx in this.blocks) {
        const b = this.blocks[idx];
        if (b.type === "tool" && b.id === c.tool_use_id && !b.done) {
          b.done = true;
          b.state.textContent = c.is_error ? "error" : "done";
          if (c.is_error) b.state.style.color = "var(--err)";
          let txt = c.content;
          if (Array.isArray(txt)) txt = txt.map((p) => p.text || "").join("");
          b.el.appendChild(el("pre", "tool-result", esc(String(txt || "").slice(0, 6000))));
        }
      }
    });
  }
  handleStreamEvent(ev) {
    const e = ev.event;
    if (!e) return;
    const wasBottom = this.atBottom();
    if (e.type === "message_start") {
      if (!this.current) this.beginAssistant();
    } else if (e.type === "content_block_start") {
      const idx = e.index, cb = e.content_block || {};
      if (cb.type === "thinking") {
        const d = el("details", "think");
        d.appendChild(el("summary", null, "thinking"));
        const tb = el("div", "think-body");
        d.appendChild(tb);
        this.current.body.appendChild(d);
        this.blocks[idx] = { type: "thinking", el: tb };
      } else if (cb.type === "text") {
        this.blocks[idx] = { type: "text", el: this.ensureTextEl() };
      } else if (cb.type === "tool_use") {
        this.blocks[idx] = this.makeToolCard(cb.name);
        this.toolInputs[idx] = "";
      }
    } else if (e.type === "content_block_delta") {
      const b = this.blocks[e.index], d = e.delta || {};
      if (!b) return;
      if (d.type === "thinking_delta") b.el.textContent += d.thinking || "";
      else if (d.type === "text_delta") {
        this.current.text += d.text || "";
        this.current.textEl.innerHTML = md(this.current.text) + '<span class="cursor">&nbsp;</span>';
      } else if (d.type === "input_json_delta") {
        this.toolInputs[e.index] += d.partial_json || "";
        b.pre.textContent = this.toolInputs[e.index];
      }
    } else if (e.type === "content_block_stop") {
      const b = this.blocks[e.index];
      if (b && b.type === "text" && this.current.textEl) this.current.textEl.innerHTML = md(this.current.text);
    }
    if (wasBottom) this.scroll();
  }

  onEvent(o) {
    switch (o.type) {
      case "system":
        if (o.subtype === "init") { this.init = o; if (this.active) fillCaps(o); }
        else if (o.subtype === "status" && o.status === "requesting") this.setStatus("thinking", "thinking");
        break;
      case "stream_event":
        if (o.event && o.event.type === "message_start") this.setStatus("working", "responding");
        this.handleStreamEvent(o);
        break;
      case "assistant":
        if (!this.current) this.beginAssistant();
        this.finalizeToolInputs(o.message || {});
        break;
      case "user":
        this.applyToolResults(o.message || {});
        break;
      case "context":
        this.ctxPct = o.pct;
        if (this.active) setCtxBadge(o.pct);
        break;
      case "result":
        this.current = null;
        this.setStatus("idle", "idle");
        this.lastUsage = usageText(o);
        if (this.active) $("#usage").textContent = this.lastUsage;
        break;
      case "stderr":
        if (/error|fatal|exception/i.test(o.text)) this.notice("stderr: " + o.text, true);
        break;
      case "process_exit":
        this.setStatus("error", "exited");
        this.notice("Claude process exited (code " + o.code + ").", true);
        break;
    }
  }

  async send(text) {
    this.addMsg("user", "Alex").textContent = text;
    this.setStatus("thinking", "thinking");
    this.beginAssistant();
    try {
      const r = await fetch("/send/" + this.id, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text }),
      });
      const j = await r.json();
      if (!j.ok) this.notice("Could not deliver message to Claude.", true);
      if (j.title && this.title === "New chat") { this.title = j.title; renderTabs(); }
    } catch (err) {
      this.notice("Send failed: " + err, true);
    }
  }

  destroy() {
    if (this.es) this.es.close();
    this.logEl.remove();
  }
}

/* ---------- top-bar reflectors (active session) ---------- */
function applyStatus(s) {
  statusEl.dataset.state = s.statusState;
  statusEl.textContent = s.statusLabel;
}
function setCtxBadge(pct) {
  $("#ctx").textContent = pct == null ? "ctx —" : "ctx " + pct + "%";
}
function fillCaps(init) {
  $("#model").textContent = init.model || "model —";
  $("#perm").textContent = "perm: " + (init.permissionMode || "—");
  chips("#capTools", init.tools);
  chips("#capMcp", init.mcp_servers);
  chips("#capSlash", init.slash_commands);
  chips("#capSkills", init.skills);
}
function chips(id, items) {
  const c = $(id);
  c.innerHTML = "";
  (items || []).forEach((it) => {
    const name = typeof it === "string" ? it : it.name;
    const span = el("span", null, esc(name));
    if (typeof it === "object" && it.status && it.status !== "connected") span.classList.add("pending");
    c.appendChild(span);
  });
}
function usageText(r) {
  const u = r.usage || {};
  const cost = r.total_cost_usd != null ? "$" + r.total_cost_usd.toFixed(4) : "";
  const tok = u.output_tokens != null ? u.output_tokens + " out" : "";
  const ms = r.duration_ms ? (r.duration_ms / 1000).toFixed(1) + "s" : "";
  return [tok, ms, cost].filter(Boolean).join("  ·  ");
}

/* ---------- tab rail ---------- */
function renderTabs() {
  tabsEl.innerHTML = "";
  sessions.forEach((s) => {
    const t = el("div", "tab" + (s.id === activeId ? " active" : ""));
    t.appendChild(el("span", "dot " + s.statusState));
    t.appendChild(el("span", "ttitle", esc(s.title)));
    const x = el("span", "tclose", "×");
    x.addEventListener("click", (ev) => { ev.stopPropagation(); closeSession(s.id); });
    t.appendChild(x);
    t.addEventListener("click", () => switchTo(s.id));
    tabsEl.appendChild(t);
  });
}
function switchTo(id) {
  const s = sessions.get(id);
  if (!s) return;
  activeId = id;
  sessions.forEach((x) => { x.logEl.hidden = x.id !== id; });
  // reflect this session into the top bar
  if (s.init) fillCaps(s.init); else { $("#model").textContent = "model —"; $("#perm").textContent = "perm —"; }
  applyStatus(s);
  setCtxBadge(s.ctxPct);
  $("#usage").textContent = s.lastUsage || "";
  renderTabs();
  s.scroll();
  input.focus();
}
async function createSession() {
  const r = await fetch("/sessions", { method: "POST" });
  const j = await r.json();
  const s = new Session(j.id, j.title);
  sessions.set(j.id, s);
  switchTo(j.id);
  return s;
}
async function closeSession(id) {
  const s = sessions.get(id);
  if (!s) return;
  await fetch("/sessions/" + id, { method: "DELETE" }).catch(() => {});
  s.destroy();
  sessions.delete(id);
  if (activeId === id) {
    const next = sessions.keys().next().value;
    if (next) switchTo(next);
    else { activeId = null; createSession(); }
  } else {
    renderTabs();
  }
}

/* periodically refresh tab status dots */
setInterval(renderTabs, 1500);

/* ---------- usage badges (5h / 7d) ---------- */
function fmtReset(ts) {
  if (!ts) return "";
  const diff = ts - Math.floor(Date.now() / 1000);
  if (diff <= 0) return "now";
  if (diff < 3600) return "<1h";
  if (diff < 86400) return Math.floor(diff / 3600) + "h";
  return Math.ceil(diff / 86400) + "d";
}
async function pollUsage() {
  try {
    const u = await (await fetch("/usage")).json();
    const r5 = $("#r5h"), r7 = $("#r7d");
    if (!u.available) { r5.textContent = "5h —"; r7.textContent = "7d —"; return; }
    const f = u.five_hour || {}, w = u.seven_day || {};
    r5.textContent = f.used_percentage != null
      ? `5h ${Math.round(f.used_percentage)}% · ${fmtReset(f.resets_at)}` : "5h —";
    r7.textContent = w.used_percentage != null
      ? `7d ${Math.round(w.used_percentage)}% · resets ${fmtReset(w.resets_at)}` : "7d —";
    const stale = u.age_seconds > 1800 ? ` (cache ${Math.round(u.age_seconds / 60)}m old)` : "";
    r5.title = "5-hour limit used" + stale;
    r7.title = "7-day limit used" + stale;
  } catch (_) {}
}
setInterval(pollUsage, 45000);
pollUsage();

/* ---------- boot greeting ---------- */
function bootGreeting() {
  fetch("/greeting").then((r) => r.json()).then((g) => {
    if (g && g.text && activeId) {
      const s = sessions.get(activeId);
      const body = s.addMsg("mist", "MIST");
      body.innerHTML = '<em class="greet">' + esc(g.text) + "</em>";
    }
  }).catch(() => {});
}

/* ---------- composer + file picker ---------- */
function insertPaths(paths) {
  if (!paths || !paths.length) return;
  const q = paths.map((p) => (/\s/.test(p) ? '"' + p + '"' : p)).join(" ");
  const cur = input.value;
  input.value = cur + (cur && !cur.endsWith(" ") ? " " : "") + q + " ";
  input.dispatchEvent(new Event("input"));
  input.focus();
}
function sendActive() {
  const text = input.value.trim();
  if (!text || !activeId) return;
  input.value = ""; input.style.height = "auto";
  sessions.get(activeId).send(text);
}
input.addEventListener("input", () => {
  input.style.height = "auto";
  input.style.height = Math.min(input.scrollHeight, 200) + "px";
});
input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendActive(); }
});
$("#sendBtn").addEventListener("click", sendActive);
$("#newTab").addEventListener("click", createSession);
$("#capBtn").addEventListener("click", () => { $("#capPanel").hidden = false; });
$("#capClose").addEventListener("click", () => { $("#capPanel").hidden = true; });

const hiddenFile = $("#hiddenFile");
$("#fileBtn").addEventListener("click", async () => {
  try {
    if (window.pywebview && window.pywebview.api && window.pywebview.api.pick_file) {
      insertPaths(await window.pywebview.api.pick_file());
    } else { hiddenFile.click(); }
  } catch (e) { if (activeId) sessions.get(activeId).notice("File picker error: " + e, true); }
});
hiddenFile.addEventListener("change", () => {
  insertPaths(Array.from(hiddenFile.files).map((f) => f.name));
  hiddenFile.value = "";
});

/* ---------- boot ---------- */
async function boot() {
  const existing = await (await fetch("/sessions")).json();
  if (existing.length) {
    existing.forEach((info) => sessions.set(info.id, new Session(info.id, info.title)));
    switchTo(existing[0].id);
  } else {
    await createSession();
  }
  bootGreeting();
  input.focus();
}
boot();

