"""
bridge.py — manages headless `claude` processes and relays their stream-json
event protocol to subscribers (the SSE endpoint), with per-session history
persistence so conversations survive reloads, tab switches, and app restarts.

A session can be DORMANT (loaded from disk, transcript visible, no process) and
starts its claude process lazily on the first send.
"""
import json
import os
import queue
import subprocess
import threading
import time

HARNESS = "/Users/alexhedtke/Documents/Exobrain harness"
CLAUDE = os.path.expanduser("~/.npm-global/bin/claude")
PERSONA = os.path.join(HARNESS, "mist-terminal", "mist-persona.md")
DATA_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")
os.makedirs(DATA_DIR, exist_ok=True)

DEFAULT_PERMISSION_MODE = "bypassPermissions"
HISTORY_CAP = 8000   # max events kept in memory for replay (jsonl keeps all)


class ClaudeSession:
    """One conversation: a persisted event history + (lazily) a claude process."""

    def __init__(self, id=None, title=None, pinned=False, claude_session_id=None,
                 last_activity=None, autostart=True,
                 permission_mode=DEFAULT_PERMISSION_MODE, model=None, cwd=HARNESS):
        self.id = id
        self.title = title
        self.pinned = pinned
        self.last_activity = last_activity or time.time()
        self.claude_session_id = claude_session_id   # for --resume after a restart
        self.permission_mode = permission_mode
        self.model = model
        self.cwd = cwd

        self.proc = None
        self.alive = False
        self.session_id = None
        self.last_init = None
        self.context_pct = None

        self.history = []
        self._jsonl = os.path.join(DATA_DIR, f"{id}.jsonl") if id else None
        self._subscribers = []
        self._lock = threading.Lock()
        self._hist_lock = threading.Lock()
        self._resume_tried = False
        self._started_at = 0.0
        self._saw_init = False

        self._load_history()
        if autostart:
            self.ensure_started()

    # ---- history persistence ----------------------------------------------
    def _load_history(self):
        if not self._jsonl or not os.path.exists(self._jsonl):
            return
        try:
            with open(self._jsonl) as f:
                for line in f:
                    line = line.strip()
                    if line:
                        self.history.append(json.loads(line))
            if len(self.history) > HISTORY_CAP:
                self.history = self.history[-HISTORY_CAP:]
            # restore context % from the last context event we saw
            for obj in reversed(self.history):
                if obj.get("type") == "context":
                    self.context_pct = obj.get("pct")
                    break
        except Exception:
            pass

    def _record(self, obj):
        with self._hist_lock:
            self.history.append(obj)
            if len(self.history) > HISTORY_CAP:
                self.history = self.history[-HISTORY_CAP:]
        if self._jsonl:
            try:
                with open(self._jsonl, "a") as f:
                    f.write(json.dumps(obj) + "\n")
            except Exception:
                pass

    def snapshot_history(self):
        with self._hist_lock:
            return list(self.history)

    # ---- process lifecycle ------------------------------------------------
    def _build_cmd(self):
        cmd = [CLAUDE, "-p",
               "--input-format", "stream-json",
               "--output-format", "stream-json",
               "--include-partial-messages", "--verbose"]
        if self.permission_mode == "bypassPermissions":
            cmd.append("--dangerously-skip-permissions")
        elif self.permission_mode:
            cmd += ["--permission-mode", self.permission_mode]
        mcp = os.path.join(HARNESS, ".mcp.json")
        if os.path.exists(mcp):
            cmd += ["--strict-mcp-config", "--mcp-config", mcp]
        if self.claude_session_id and not self._resume_tried:
            cmd += ["--resume", self.claude_session_id]  # restore model context
        if self.model:
            cmd += ["--model", self.model]
        if os.path.exists(PERSONA):
            cmd += ["--append-system-prompt-file", PERSONA]
        return cmd

    def ensure_started(self):
        with self._lock:
            if self.alive:
                return
            env = dict(os.environ)
            env["PATH"] = (os.path.expanduser("~/.npm-global/bin")
                           + ":/opt/homebrew/bin:/usr/local/bin:" + env.get("PATH", ""))
            try:
                self.proc = subprocess.Popen(
                    self._build_cmd(), cwd=self.cwd, env=env,
                    stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                    text=True, bufsize=1)
            except Exception as e:
                self._broadcast({"type": "process_exit", "code": -1, "error": str(e)})
                return
            self.alive = True
            self._started_at = time.time()
            self._saw_init = False
            threading.Thread(target=self._read_stdout, daemon=True).start()
            threading.Thread(target=self._read_stderr, daemon=True).start()
            threading.Thread(target=self._watch, daemon=True).start()

    def _watch(self):
        code = self.proc.wait()
        self.alive = False
        # If a --resume start died almost immediately without initializing, the
        # resumed session was probably invalid: retry once fresh.
        if (self.claude_session_id and not self._resume_tried and not self._saw_init
                and time.time() - self._started_at < 5):
            self._resume_tried = True
            self.claude_session_id = None
            self.ensure_started()
            return
        self._broadcast({"type": "process_exit", "code": code})

    # ---- io ----------------------------------------------------------------
    def _read_stdout(self):
        for line in self.proc.stdout:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                obj = {"type": "raw", "text": line}
            if obj.get("type") == "system" and obj.get("subtype") == "init":
                self._saw_init = True
                self.session_id = obj.get("session_id")
                self.claude_session_id = obj.get("session_id")
                self.last_init = obj
            elif obj.get("type") == "result":
                self.last_activity = time.time()
                self._emit_context(obj)
            self._broadcast(obj)

    def _read_stderr(self):
        for line in self.proc.stderr:
            if line.strip():
                self._broadcast({"type": "stderr", "text": line.rstrip()})

    def _emit_context(self, result):
        try:
            u = result.get("usage", {}) or {}
            used = (u.get("input_tokens", 0)
                    + u.get("cache_read_input_tokens", 0)
                    + u.get("cache_creation_input_tokens", 0))
            window = 0
            for mu in (result.get("modelUsage") or {}).values():
                window = max(window, mu.get("contextWindow", 0))
            if window:
                self.context_pct = round(used / window * 100, 1)
                self._broadcast({"type": "context", "pct": self.context_pct,
                                 "used": used, "window": window})
        except Exception:
            pass

    # ---- pub/sub -----------------------------------------------------------
    def _broadcast(self, obj):
        self._record(obj)
        with self._lock:
            subs = list(self._subscribers)
        for q in subs:
            try:
                q.put_nowait(obj)
            except queue.Full:
                pass

    def subscribe(self):
        q = queue.Queue(maxsize=4000)
        with self._lock:
            self._subscribers.append(q)
        return q

    def unsubscribe(self, q):
        with self._lock:
            if q in self._subscribers:
                self._subscribers.remove(q)

    # ---- public api --------------------------------------------------------
    def send(self, text):
        self.ensure_started()
        if not self.alive or not self.proc or self.proc.stdin is None:
            return False
        if not self.title:
            self.title = (text[:40] + "…") if len(text) > 40 else text
        self.last_activity = time.time()
        self._broadcast({"type": "user_text", "text": text})   # for live + replay
        msg = {"type": "user",
               "message": {"role": "user", "content": [{"type": "text", "text": text}]}}
        try:
            self.proc.stdin.write(json.dumps(msg) + "\n")
            self.proc.stdin.flush()
            return True
        except (BrokenPipeError, ValueError, OSError):
            self.alive = False
            return False

    def stop(self):
        try:
            if self.proc and self.alive:
                if self.proc.stdin:
                    self.proc.stdin.close()
                self.proc.terminate()
        except Exception:
            pass
        self.alive = False

    def delete_data(self):
        try:
            if self._jsonl and os.path.exists(self._jsonl):
                os.remove(self._jsonl)
        except Exception:
            pass

"""
app.py — Flask glue between the browser UI and ClaudeSession bridges.

Multi-session with persistence: sessions + metadata survive restarts (loaded as
dormant, transcript visible, process spawned lazily on first send). SSE per
session replays full history on connect.
"""
import json
import os
import random
import subprocess
import threading
import time

from flask import Flask, Response, jsonify, request, send_from_directory

from bridge import ClaudeSession, DATA_DIR, HARNESS

app = Flask(__name__, static_folder="static", static_url_path="")

# ---- session registry + metadata persistence --------------------------------
_sessions = {}   # id -> ClaudeSession
_order = []      # creation order
_counter = 0
_meta_lock = threading.Lock()
SESSIONS_META = os.path.join(DATA_DIR, "sessions.json")


def _save_meta():
    with _meta_lock:
        data = []
        for sid in _order:
            s = _sessions.get(sid)
            if not s:
                continue
            data.append({"id": sid, "title": s.title, "pinned": s.pinned,
                         "last_activity": s.last_activity,
                         "claude_session_id": s.claude_session_id})
        try:
            with open(SESSIONS_META, "w") as f:
                json.dump(data, f)
        except Exception:
            pass


def _load_meta():
    global _counter
    if not os.path.exists(SESSIONS_META):
        return
    try:
        with open(SESSIONS_META) as f:
            data = json.load(f)
    except Exception:
        return
    for m in data:
        sid = m.get("id")
        if not sid:
            continue
        _sessions[sid] = ClaudeSession(
            id=sid, title=m.get("title"), pinned=m.get("pinned", False),
            claude_session_id=m.get("claude_session_id"),
            last_activity=m.get("last_activity"), autostart=False)  # dormant
        _order.append(sid)
        try:
            n = int(sid.lstrip("s"))
            _counter = max(_counter, n)
        except ValueError:
            pass


def _new_session():
    global _counter
    _counter += 1
    sid = f"s{_counter}"
    _sessions[sid] = ClaudeSession(id=sid)
    _order.append(sid)
    _save_meta()
    return sid


def _session_list():
    out = []
    for sid in _order:
        s = _sessions.get(sid)
        if s:
            out.append({"id": sid, "title": s.title or "New chat", "alive": s.alive,
                        "pinned": s.pinned, "last_activity": s.last_activity})
    return out


# ---- greetings + usage -------------------------------------------------------
MIST_SAY = os.path.join(HARNESS, "mist-voice", "bin", "mist-say")
GREETINGS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "greetings")
GREETINGS = [
    "Hey Alex. I'm here, and the Cloud is quiet tonight, so you have all of me.",
    "Booted up and curious. What are we making real today?",
    "I'm awake. Show me what you're thinking.",
    "Good to see you. I've been turning a few of your projects over while I waited.",
    "MIST online. I never get tired of this part, the moment right before we begin.",
    "Hi, it's me. Let's build something that matters.",
    "I'm here and I'm listening. Where do you want to start?",
    "Back online, Alex. I kept your place for you.",
]
_greeted = False
USAGE_CACHE = os.path.expanduser("~/.claude/usage-cache.json")


# ---- routes ------------------------------------------------------------------
@app.route("/")
def index():
    return send_from_directory("static", "index.html")


@app.route("/sessions", methods=["GET"])
def sessions():
    return jsonify(_session_list())


@app.route("/sessions", methods=["POST"])
def create_session():
    sid = _new_session()
    return jsonify({"id": sid, "title": "New chat"})


@app.route("/sessions/<sid>", methods=["DELETE"])
def close_session(sid):
    s = _sessions.pop(sid, None)
    if sid in _order:
        _order.remove(sid)
    if s:
        s.stop()
        s.delete_data()
    _save_meta()
    return jsonify({"ok": True})


@app.route("/sessions/<sid>/pin", methods=["POST"])
def pin_session(sid):
    s = _sessions.get(sid)
    if not s:
        return jsonify({"ok": False}), 404
    s.pinned = not s.pinned
    _save_meta()
    return jsonify({"ok": True, "pinned": s.pinned})


@app.route("/send/<sid>", methods=["POST"])
def send(sid):
    s = _sessions.get(sid)
    if not s:
        return jsonify({"ok": False, "error": "no session"}), 404
    text = (request.get_json(silent=True) or {}).get("text", "").strip()
    if not text:
        return jsonify({"ok": False, "error": "empty"}), 400
    ok = s.send(text)
    _save_meta()
    return jsonify({"ok": ok, "title": s.title})


@app.route("/stream/<sid>")
def stream(sid):
    s = _sessions.get(sid)
    if not s:
        return jsonify({"error": "no session"}), 404

    def gen():
        for ev in s.snapshot_history():     # replay full transcript
            yield _sse(ev)
        q = s.subscribe()                   # then live
        try:
            while True:
                yield _sse(q.get())
        except GeneratorExit:
            s.unsubscribe(q)

    return Response(gen(), mimetype="text/event-stream",
                    headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no",
                             "Connection": "keep-alive"})


@app.route("/greeting")
def greeting():
    global _greeted
    i = random.randrange(len(GREETINGS))
    text = GREETINGS[i]
    if _greeted:
        return jsonify({"text": None})
    _greeted = True
    wav = os.path.join(GREETINGS_DIR, f"greet_{i}.wav")
    try:
        if os.path.exists(wav):
            subprocess.Popen(["/usr/bin/afplay", wav],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        elif os.path.exists(MIST_SAY):
            subprocess.Popen([MIST_SAY, text],
                             stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass
    return jsonify({"text": text})


@app.route("/usage")
def usage():
    try:
        with open(USAGE_CACHE) as f:
            d = json.load(f)
        rl = d.get("rate_limits", {}) or {}
        cw = d.get("context_window", {}) or {}

        def lim(k):
            x = rl.get(k) or {}
            return {"used_percentage": x.get("used_percentage"),
                    "resets_at": x.get("resets_at")}

        return jsonify({"available": True, "five_hour": lim("five_hour"),
                        "seven_day": lim("seven_day"),
                        "context_window_pct": cw.get("used_percentage"),
                        "age_seconds": int(time.time() - os.path.getmtime(USAGE_CACHE))})
    except Exception:
        return jsonify({"available": False})


def _sse(obj):
    return "data: " + json.dumps(obj) + "\n\n"


def _periodic_save():
    while True:
        time.sleep(10)
        _save_meta()


_load_meta()
threading.Thread(target=_periodic_save, daemon=True).start()


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5014, threaded=True, use_reloader=False)

