"""
quickaccess.py — a global "summon MIST" hotkey (like Claude Desktop's Quick
Access Shortcut). Uses a Cocoa global key monitor (no extra dependency).

The monitor only fires while MIST is in the background (another app focused),
which is exactly the summon case. macOS asks for Input Monitoring permission
the first time. Matching is by modifier flags + the base character, so we don't
have to map keycodes.
"""
import json
import os

CONFIG = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data", "quick_access.json")
DEFAULT = {"enabled": True, "key": "m", "cmd": True, "shift": True, "ctrl": False, "alt": False}

# NSEvent modifier flag masks
_CMD, _SHIFT, _CTRL, _ALT = 1 << 20, 1 << 17, 1 << 18, 1 << 19
_MASK_KEYDOWN = 1 << 10  # NSEventMaskKeyDown

_cfg = dict(DEFAULT)
_monitor = None
_show_fn = None


def load():
    global _cfg
    try:
        with open(CONFIG) as f:
            _cfg = {**DEFAULT, **json.load(f)}
    except Exception:
        _cfg = dict(DEFAULT)
    return dict(_cfg)


def get():
    return dict(_cfg)


def save(cfg):
    global _cfg
    _cfg = {**DEFAULT, **(cfg or {})}
    try:
        os.makedirs(os.path.dirname(CONFIG), exist_ok=True)
        with open(CONFIG, "w") as f:
            json.dump(_cfg, f)
    except Exception:
        pass
    return dict(_cfg)


def _matches(event):
    if not _cfg.get("enabled"):
        return False
    flags = int(event.modifierFlags())
    if bool(flags & _CMD) != bool(_cfg.get("cmd")):
        return False
    if bool(flags & _SHIFT) != bool(_cfg.get("shift")):
        return False
    if bool(flags & _CTRL) != bool(_cfg.get("ctrl")):
        return False
    if bool(flags & _ALT) != bool(_cfg.get("alt")):
        return False
    chars = (event.charactersIgnoringModifiers() or "")
    return str(chars).lower() == str(_cfg.get("key", "")).lower()


def install_monitor(show_fn):
    """Install the global key monitor. show_fn() is called on the main thread
    when the configured shortcut is pressed while another app is focused."""
    global _monitor, _show_fn
    _show_fn = show_fn
    try:
        from AppKit import NSEvent

        def handler(event):
            try:
                if _matches(event) and _show_fn:
                    _show_fn()
            except Exception:
                pass

        _monitor = NSEvent.addGlobalMonitorForEventsMatchingMask_handler_(
            _MASK_KEYDOWN, handler)
    except Exception as e:
        print("quick-access: monitor install failed:", e)

