/* ---------- quick access shortcut ---------- */
let qaCfg = { enabled: true, key: "m", cmd: true, shift: true, ctrl: false, alt: false };
function formatCombo(c) {
  if (!c || !c.key) return "—";
  let s = "";
  if (c.ctrl) s += "⌃";
  if (c.alt) s += "⌥";
  if (c.shift) s += "⇧";
  if (c.cmd) s += "⌘";
  return s + (c.key === " " ? "Space" : c.key.toUpperCase());
}
async function loadQuickAccess() {
  try { qaCfg = await (await fetch("/quick-access")).json(); } catch (_) {}
  $("#qaEnabled").checked = !!qaCfg.enabled;
  $("#qaRecord").textContent = formatCombo(qaCfg);
}
async function saveQuickAccess() {
  $("#qaRecord").textContent = formatCombo(qaCfg);
  try {
    await fetch("/quick-access", {
      method: "POST", headers: { "Content-Type": "application/json" },
      body: JSON.stringify(qaCfg),
    });
  } catch (_) {}
}
$("#qaEnabled").addEventListener("change", (e) => { qaCfg.enabled = e.target.checked; saveQuickAccess(); });
$("#qaRecord").addEventListener("click", () => {
  const btn = $("#qaRecord");
  btn.textContent = "press shortcut…";
  btn.classList.add("recording");
  function cleanup() {
    document.removeEventListener("keydown", onKey, true);
    btn.classList.remove("recording");
    btn.textContent = formatCombo(qaCfg);
  }
  function onKey(e) {
    e.preventDefault(); e.stopPropagation();
    if (e.key === "Escape") return cleanup();
    if (["Meta", "Shift", "Control", "Alt"].includes(e.key)) return;  // wait for a real key
    if (e.key.length !== 1) return;                                    // single char only
    if (!(e.metaKey || e.shiftKey || e.ctrlKey || e.altKey)) return;  // require a modifier
    qaCfg = { enabled: true, key: e.key.toLowerCase(),
              cmd: e.metaKey, shift: e.shiftKey, ctrl: e.ctrlKey, alt: e.altKey };
    $("#qaEnabled").checked = true;
    cleanup();
    saveQuickAccess();
  }
  document.addEventListener("keydown", onKey, true);
});
